using Dapper;
using Valora.Application.Contracts;
using Valora.Application.DTOs;
namespace Valora.Infrastructure.Repositories;

public sealed class ReportRepository(IDbConnectionFactory f) : IReportRepository { private const string Projection="id,organization_id OrganizationId,survey_id SurveyId,response_id ResponseId,title,format,status,payload_json::text PayloadJson,file_name FileName,mime_type MimeType,created_at CreatedAt"; public async Task<IReadOnlyList<ReportDefinitionDto>> ListDefinitionsAsync() { using var c = f.Create(); return (await c.QueryAsync<ReportDefinitionDto>("SELECT id,code,name,description,report_type AS ReportType,required_module_code AS RequiredModuleCode,minimum_plan_code AS MinimumPlanCode,status FROM valorapesquisa.report_definitions WHERE is_deleted=false")).ToList(); } public async Task<GeneratedReportDto> CreateGeneratedAsync(Guid o, Guid? s, Guid? r, Guid? d, string title, string format, string payloadJson, Guid? u) { using var c = f.Create();var extension=format=="csv"?"csv":"json";var mime=format=="csv"?"text/csv":"application/json";var storedPayload=format=="csv"?System.Text.Json.JsonSerializer.Serialize(payloadJson):payloadJson; return await c.QuerySingleAsync<GeneratedReportDto>($@"INSERT INTO valorapesquisa.generated_reports(organization_id,survey_id,response_id,report_definition_id,title,format,status,generated_by,generated_at,payload_json,file_name,mime_type) VALUES(@o,@s,@r,@d,@title,@format,'generated',@u,now(),CAST(@storedPayload AS jsonb),@file,@mime) RETURNING {Projection}", new { o, s, r, d, title, format, storedPayload, u, file = $"relatorio-executivo-{DateTime.UtcNow:yyyyMMddHHmmss}.{extension}", mime }); } public async Task<GeneratedReportDto?> FindGeneratedAsync(Guid o,Guid? s,Guid? r,string format){using var c=f.Create();return await c.QueryFirstOrDefaultAsync<GeneratedReportDto>($"SELECT {Projection} FROM valorapesquisa.generated_reports gr WHERE gr.organization_id=@o AND gr.survey_id IS NOT DISTINCT FROM @s AND gr.response_id IS NOT DISTINCT FROM @r AND gr.format=@format AND gr.status='generated' AND (@s IS NULL OR NOT EXISTS (SELECT 1 FROM valorapesquisa.responses source_response WHERE source_response.organization_id=@o AND source_response.survey_id=@s AND source_response.is_deleted=false AND greatest(source_response.created_at,coalesce(source_response.updated_at,source_response.created_at),coalesce(source_response.completed_at,source_response.created_at))>gr.created_at)) ORDER BY gr.created_at DESC LIMIT 1",new{o,s,r,format});} public async Task<IReadOnlyList<GeneratedReportDto>> ListGeneratedAsync(Guid o) { using var c = f.Create(); return (await c.QueryAsync<GeneratedReportDto>($"SELECT {Projection} FROM valorapesquisa.generated_reports WHERE organization_id=@o ORDER BY created_at DESC", new { o })).ToList(); } public async Task<GeneratedReportDto?> GetGeneratedAsync(Guid o, Guid id) { using var c = f.Create(); return await c.QueryFirstOrDefaultAsync<GeneratedReportDto>($"SELECT {Projection} FROM valorapesquisa.generated_reports WHERE organization_id=@o AND id=@id", new { o, id }); } }
